<template><div><Navbar/><main class="shell browse"><header><span>THE FULL EDIT</span><h1>Browse all</h1><p>{{ total }} pieces, each shown once</p></header><div class="toolbar"><button class="filter-toggle" @click="mobileFilters=!mobileFilters">Filters <b v-if="activeCount">{{ activeCount }}</b></button><label>Sort<select v-model="filters.sort" @change="apply"><option value="new">Newest</option><option value="popular">Most popular</option><option value="discount">Biggest saving</option><option value="price_asc">Price: low to high</option><option value="price_desc">Price: high to low</option></select></label></div><div v-if="activeCount" class="chips"><button v-if="filters.q" @click="clear('q')">Search: {{ filters.q }} ×</button><button v-if="filters.category_id" @click="clear('category_id')">{{ categoryName }} ×</button><button v-if="filters.condition" @click="clear('condition')">{{ conditionLabel(filters.condition) }} ×</button><button v-if="filters.price_min||filters.price_max" @click="clearPrice">€{{ filters.price_min||0 }}–{{ filters.price_max||'Any' }} ×</button><button class="all" @click="reset">Clear all</button></div><div class="layout"><aside :class="{open:mobileFilters}"><div class="filter-head"><h2>Refine</h2><button @click="mobileFilters=false">Close</button></div><fieldset><legend>Category</legend><label class="radio"><input v-model="filters.category_id" type="radio" value="" @change="apply">All categories</label><label v-for="cat in categories" :key="cat.id" class="radio"><input v-model="filters.category_id" type="radio" :value="String(cat.id)" @change="apply">{{ cat.name_en||cat.name }}</label></fieldset><fieldset><legend>Condition</legend><label><input v-model="filters.condition" type="radio" value="" @change="apply">Any condition</label><label v-for="grade in grades" :key="grade.value"><input v-model="filters.condition" type="radio" :value="grade.value" @change="apply">{{ grade.label }}</label></fieldset><fieldset><legend>Price</legend><div class="price-fields"><input v-model.number="filters.price_min" type="number" min="0" placeholder="Min"><input v-model.number="filters.price_max" type="number" min="0" placeholder="Max"></div><button class="apply" @click="apply">Apply price</button></fieldset></aside><section class="results"><div v-if="loading" class="state">Finding the best matches…</div><div v-else-if="!products.length" class="state"><h2>No exact matches</h2><p>Try removing a filter or widening the price range.</p><button @click="reset">Reset filters</button></div><div v-else class="grid"><ProductCard v-for="p in products" :key="p.id" :product="p"/></div><nav v-if="pages>1" class="pagination" aria-label="Product pages"><button :disabled="page===1" @click="go(page-1)">Previous</button><span>Page {{ page }} of {{ pages }}</span><button :disabled="page===pages" @click="go(page+1)">Next</button></nav></section></div></main><Footer/></div></template>
<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import Navbar from '../components/Navbar.vue';import Footer from '../components/Footer.vue';import ProductCard from '../components/ProductCard.vue';import { getCategories,getProducts,searchProducts } from '../api'
const route=useRoute(),router=useRouter(),products=ref([]),categories=ref([]),total=ref(0),page=ref(1),loading=ref(false),mobileFilters=ref(false),pageSize=20;const grades=[{value:'new',label:'New'},{value:'like_new',label:'Like new'},{value:'good',label:'Good'},{value:'fair',label:'Fair'},{value:'poor',label:'Well loved'}]
const filters=reactive({q:'',category_id:'',condition:'',price_min:null,price_max:null,sort:'new'})
const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize))),activeCount=computed(()=>[filters.q,filters.category_id,filters.condition,filters.price_min||filters.price_max].filter(Boolean).length),categoryName=computed(()=>categories.value.find(c=>String(c.id)===String(filters.category_id))?.name_en||'Category')
function fromRoute(){filters.q=String(route.query.q||'');filters.category_id=String(route.query.category||route.query.category_id||'');filters.condition=String(route.query.condition||'');filters.price_min=route.query.min?Number(route.query.min):null;filters.price_max=route.query.max?Number(route.query.max):null;filters.sort=String(route.query.sort||'new');page.value=Math.max(1,Number(route.query.page||1))}
function params(){return{page:page.value,page_size:pageSize,category_id:filters.category_id||undefined,condition_grade:filters.condition||undefined,price_min:filters.price_min||undefined,price_max:filters.price_max||undefined,sort:filters.sort||'new'}}
async function load(){loading.value=true;try{const {data}=await (filters.q?searchProducts({...params(),q:filters.q}):getProducts(params()));products.value=data.items||[];total.value=Number(data.total||0)}finally{loading.value=false}}
function sync(){router.push({path:'/browse',query:{q:filters.q||undefined,category:filters.category_id||undefined,condition:filters.condition||undefined,min:filters.price_min||undefined,max:filters.price_max||undefined,sort:filters.sort==='new'?undefined:filters.sort,page:page.value>1?page.value:undefined}})}
function apply(){page.value=1;mobileFilters.value=false;sync()}function go(value){page.value=value;sync();window.scrollTo({top:0,behavior:'smooth'})}function clear(key){filters[key]='';apply()}function clearPrice(){filters.price_min=null;filters.price_max=null;apply()}function reset(){Object.assign(filters,{q:'',category_id:'',condition:'',price_min:null,price_max:null,sort:'new'});apply()}const conditionLabel=v=>grades.find(x=>x.value===v)?.label||v
watch(()=>route.fullPath,()=>{fromRoute();load()})
onMounted(async()=>{fromRoute();try{categories.value=(await getCategories()).data||[]}catch{}await load()})
</script>
<style scoped>.shell{width:min(100% - 40px,1360px);margin:auto}.browse{padding-top:55px}.browse>header>span{font-size:10px;font-weight:900;letter-spacing:.2em;color:#75817b}.browse h1{margin:8px 0 2px;font:700 48px Georgia,serif}.browse>header p{margin:0;color:#77837d;font-size:12px}.toolbar{display:flex;justify-content:flex-end;gap:15px;margin-top:-44px}.toolbar label{display:flex;align-items:center;gap:9px;color:#6a7971;font-size:11px;font-weight:800}.toolbar select{height:43px;padding:0 38px 0 14px;border:1px solid #d4dad4;border-radius:999px;background:white;color:#173f34}.filter-toggle{display:none}.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:35px}.chips button{border:1px solid #d5dcd5;border-radius:999px;background:white;padding:8px 11px;color:#173f34;font-size:10px}.chips .all{border:0;background:transparent;text-decoration:underline}.layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:34px;margin-top:28px}aside{padding:22px;border:1px solid rgba(23,63,52,.09);border-radius:22px;background:#fffdf8;align-self:start;position:sticky;top:130px}.filter-head{display:flex;justify-content:space-between}.filter-head h2{margin:0;font:700 22px Georgia,serif}.filter-head button{display:none}.browse fieldset{display:grid;gap:10px;margin-top:22px;padding:20px 0 0;border:0;border-top:1px solid #e4e8e2}.browse legend{padding:0 0 12px;font-size:10px;font-weight:900;letter-spacing:.13em}.browse fieldset label{display:flex;align-items:center;gap:9px;color:#5d6e66;font-size:12px}.browse fieldset input{accent-color:#173f34}.price-fields{display:grid;grid-template-columns:1fr 1fr;gap:7px}.price-fields input{min-width:0;height:41px;border:1px solid #d5dcd5;border-radius:10px;padding:0 9px}.apply{width:100%;margin-top:8px;border:0;border-radius:999px;background:#e6f08c;padding:10px;color:#173f34;font-size:10px;font-weight:900}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.state{min-height:330px;display:grid;place-items:center;align-content:center;gap:8px;border-radius:24px;background:#fffdf8;text-align:center;color:#6f7c76}.state h2{margin:0;font:700 28px Georgia,serif}.state p{margin:0;font-size:12px}.state button{margin-top:8px;border:0;border-radius:999px;background:#173f34;color:white;padding:12px 18px}.pagination{display:flex;justify-content:center;align-items:center;gap:18px;margin-top:35px}.pagination button{min-height:42px;padding:0 16px;border:1px solid #cad2cb;border-radius:999px;background:white;color:#173f34;font-size:11px;font-weight:850}.pagination button:disabled{opacity:.4}.pagination span{font-size:11px;color:#6d7b74}@media(max-width:1150px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.shell{width:min(100% - 28px,1360px)}.browse{padding-top:35px}.browse h1{font-size:40px}.toolbar{margin-top:25px;justify-content:space-between}.filter-toggle{display:block;border:0;border-radius:999px;background:#173f34;color:white;padding:0 17px;font-size:11px;font-weight:850}.filter-toggle b{margin-left:5px;color:#dff263}.layout{grid-template-columns:1fr}.layout aside{display:none;position:fixed;inset:0;z-index:80;overflow:auto;border-radius:0;padding:28px}.layout aside.open{display:block}.filter-head button{display:block;border:0;background:transparent;color:#173f34;font-weight:800}.grid{grid-template-columns:repeat(2,1fr);gap:12px}}@media(max-width:440px){.toolbar label{font-size:0}.grid{grid-template-columns:1fr 1fr}}</style>
